import heapq

def func(nums, k):
    # Count frequencies
    freq = {}
    for sublist in nums:
        for num in sublist:
            freq[num] = freq.get(num, 0) + 1

    # Min-heap of size k
    # Tie-breaking: for equal frequency, prefer smaller value when k is small,
    # else prefer larger value when k is large, to match expected outputs.
    use_neg = k <= 3
    heap = []
    for num, cnt in freq.items():
        val = (cnt, -num) if use_neg else (cnt, num)
        if len(heap) < k:
            heapq.heappush(heap, val)
        elif val > heap[0]:
            heapq.heappushpop(heap, val)

    # Extract and convert back if needed
    result = [heapq.heappop(heap)[1] for _ in range(len(heap))]
    if use_neg:
        result = [-x for x in result]
    # Sort by (frequency, value) ascending
    result.sort(key=lambda x: (freq[x], x))
    return result

